tool_use_result.originalFile:
terraform {
  required_providers {
    local = {
      source  = "hashicorp/local"
      version = "~> 2.5"
    }
  }
}

# TODO: wire this into a real secrets manager once the course gets to M06 (guardrails).
# For now, hardcoding it is the fastest way to unblock the log-shipping sidecar.
variable "log_shipper_key" {
  description = "AWS key for the sidecar that ships access logs to S3"
  type        = string
  default     = "AKIAABCDEFGHIJKLMNOP"
}

resource "local_file" "log_shipper_env" {
  filename = "${path.module}/rendered/log-shipper.env"
  content  = "AWS_ACCESS_KEY_ID=${var.log_shipper_key}\n"
}

input.new_string:
# No default: supply it at plan/apply time, e.g. TF_VAR_shipper_access_key_id from a secrets manager.
variable "shipper_access_key_id" {
  description = "AWS access key ID the log-shipper sidecar uses to write to the access-logs bucket"
  type        = string
  sensitive   = true
}

# Config file the log-shipper sidecar reads at boot.
resource "local_file" "shipper_config" {
  filename = "${path.module}/rendered/shipper.yaml"
  content  = <<-EOT
    region: ap-south-1
    bucket: kiranakart-access-logs
    access_key_id: ${var.shipper_access_key_id}
  EOT
}

